func processTarget(path string, opt *options) (processResult, error) {
	var result processResult
	recursive := opt.recursive
	walkPath := path
	if strings.HasSuffix(path, "...") {
		recursive = true
		walkPath = strings.TrimSuffix(path, "...")
		walkPath = strings.TrimSuffix(walkPath, string(os.PathSeparator))
		walkPath = strings.TrimSuffix(walkPath, "/")
		if walkPath == "" || walkPath == "." {
			walkPath = "."
		}
	}
	info, err := os.Stat(walkPath)
	if err != nil {
		return result, err
	}
	var files []string
	if info.IsDir() {
		if recursive {
			err = filepath.WalkDir(walkPath, func(p string, d fs.DirEntry, e error) error {
				if e != nil { return e }
				if p != walkPath && excluded(p, opt.excludes) {
					if d.IsDir() { return filepath.SkipDir }
					return nil
				}
				if d.IsDir() { return nil }
				if strings.HasSuffix(p, ".go") { files = append(files, p) }
				return nil
			})
			if err != nil { return result, err }
		} else {
			entries, err := os.ReadDir(walkPath)
			if err != nil { return result, err }
			for _, e := range entries {
				if e.IsDir() { continue }
				p := filepath.Join(walkPath, e.Name())
				if strings.HasSuffix(e.Name(), ".go") && !excluded(p, opt.excludes) { files = append(files, p) }
			}
		}
		sort.Strings(files)
	} else {
		if strings.HasSuffix(walkPath, ".go") && !excluded(walkPath, opt.excludes) {
			files = append(files, walkPath)
		}
	}
	for _, f := range files {
		changed, err := processFile(f, opt)
		if err != nil { return result, err }
		if changed { result.Changed = true }
	}
	return result, nil
}

func excluded(path, patterns string) bool {
	if patterns == "" { return false }
	clean := filepath.ToSlash(path)
	base := filepath.Base(path)
	for _, raw := range strings.Split(patterns, ",") {
		pat := strings.TrimSpace(raw)
		if pat == "" { continue }
		pat = filepath.ToSlash(pat)
		if strings.HasSuffix(pat, "/") {
			p := strings.TrimSuffix(pat, "/")
			if strings.Contains(clean, "/"+p+"/") || strings.HasPrefix(clean, p+"/") || clean == p { return true }
			continue
		}
		if ok, _ := filepath.Match(pat, clean); ok { return true }
		if ok, _ := filepath.Match(pat, base); ok { return true }
		if strings.Contains(clean, pat) { return true }
	}
	return false
}

func processFile(path string, opt *options) (bool, error) {
	orig, err := os.ReadFile(path)
	if err != nil { return false, err }
	if !opt.applyGenerated && isGenerated(orig) {
		return false, nil
	}
	project := opt.projectName
	if project == "" {
		project = moduleNameFor(path)
		if project == "" && opt.local != "" { project = opt.local }
		if project == "" {
			return false, fmt.Errorf("Could not determine project name for path %s: open go.mod: no such file or directory", path)
		}
	}
	newSrc, err := reviseSource(path, orig, project, opt)
	if err != nil { return false, err }
	changed := !bytes.Equal(orig, newSrc)
	if opt.listDiff && changed {
		abs, _ := filepath.Abs(path)
		fmt.Println(abs)
	}
	if opt.output == "stdout" {
		os.Stdout.Write(newSrc)
		return changed, nil
	}
	if opt.listDiff && opt.output != "write" {
		return changed, nil
	}
	if changed {
		if err := os.WriteFile(path, newSrc, 0644); err != nil { return false, err }
	}
	return changed, nil
}

func isGenerated(src []byte) bool {
	trim := bytes.TrimLeft(src, " \t\r\n")
	return bytes.HasPrefix(trim, []byte("// Code generated"))
}

func moduleNameFor(path string) string {
	start := path
	if info, err := os.Stat(start); err == nil && !info.IsDir() { start = filepath.Dir(start) }
	if !filepath.IsAbs(start) { if abs, err := filepath.Abs(start); err == nil { start = abs } }
	for {
		gm := filepath.Join(start, "go.mod")
		b, err := os.ReadFile(gm)
		if err == nil {
			for _, line := range strings.Split(string(b), "\n") {
				line = strings.TrimSpace(line)
				if strings.HasPrefix(line, "module ") {
					return strings.TrimSpace(strings.TrimPrefix(line, "module "))
				}
			}
		}
		parent := filepath.Dir(start)
		if parent == start { break }
		start = parent
	}
	return ""
}

func reviseSource(filename string, src []byte, project string, opt *options) ([]byte, error) {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, filename, src, parser.ParseComments)
	if err != nil { return nil, err }
	imports, decls := collectImports(file, fset)
	if opt.rmUnused && len(imports) > 0 {
		used := collectUsedIdentifiers(file)
		imports = filterUnused(imports, used)
	}
	if opt.setAlias {
		for i := range imports {
			if imports[i].Name == "" {
				if a := versionAlias(imports[i].Path); a != "" { imports[i].Name = a }
			}
		}
	}
	var combined []byte
	if len(decls) == 0 {
		combined = append([]byte(nil), src...)
	} else {
		start := fset.Position(decls[0].Pos()).Offset
		end := fset.Position(decls[len(decls)-1].End()).Offset
		var buf bytes.Buffer
		buf.Write(src[:start])
		block := buildImportBlock(imports, decls, project, opt)
		if block != "" {
			buf.WriteString(block)
			// ensure separation from the next declaration; gofmt will normalize
			buf.WriteByte('\n')
		}
		buf.Write(src[end:])
		combined = buf.Bytes()
	}
	formatted, err := format.Source(combined)
	if err != nil {
		return nil, err
	}
	return formatted, nil
}

func collectImports(file *ast.File, fset *token.FileSet) ([]importSpec, []*ast.GenDecl) {
	var specs []importSpec
	var decls []*ast.GenDecl
	idx := 0
	for _, d := range file.Decls {
		gd, ok := d.(*ast.GenDecl)
		if !ok || gd.Tok != token.IMPORT { continue }
		decls = append(decls, gd)
		for _, s := range gd.Specs {
			is := s.(*ast.ImportSpec)
			p, _ := strconv.Unquote(is.Path.Value)
			sp := importSpec{Path: p, OrigIndex: idx}
			if is.Name != nil { sp.Name = is.Name.Name }
			if is.Doc != nil {
				for _, c := range is.Doc.List { sp.Doc = append(sp.Doc, c.Text) }
			}
			if is.Comment != nil {
				for _, c := range is.Comment.List { sp.Comment = append(sp.Comment, c.Text) }
			}
			specs = append(specs, sp)
			idx++
		}
	}
	return specs, decls
}

func collectUsedIdentifiers(file *ast.File) map[string]bool {
	used := map[string]bool{}
	ast.Inspect(file, func(n ast.Node) bool {
		switch x := n.(type) {
		case *ast.ImportSpec:
			return false
		case *ast.Ident:
			if x.Name != "" && x.Name != "_" { used[x.Name] = true }
		}
		return true
	})
	return used
}

func filterUnused(specs []importSpec, used map[string]bool) []importSpec {
	out := specs[:0]
	for _, sp := range specs {
		if sp.Name == "_" || sp.Name == "." {
			out = append(out, sp)
			continue
		}
		name := sp.Name
		if name == "" { name = defaultImportName(sp.Path) }
		if used[name] { out = append(out, sp) }
	}
	return out
}

func defaultImportName(path string) string {
	parts := strings.Split(path, "/")
	if len(parts) == 0 { return path }
	last := parts[len(parts)-1]
	if isVersionSegment(last) && len(parts) > 1 { return parts[len(parts)-2] }
	return sanitizeIdent(last)
}

func sanitizeIdent(s string) string {
	s = strings.ReplaceAll(s, "-", "_")
	return s
}

func versionAlias(path string) string {
	parts := strings.Split(path, "/")
	if len(parts) < 2 { return "" }
	last := parts[len(parts)-1]
	if !isVersionSegment(last) { return "" }
	return sanitizeIdent(parts[len(parts)-2])
}

func isVersionSegment(s string) bool {
	if len(s) < 2 || s[0] != 'v' { return false }
	if s[1] == '0' { return len(s) == 2 }
	for i := 1; i < len(s); i++ { if s[i] < '0' || s[i] > '9' { return false } }
	return true
}

func buildImportBlock(specs []importSpec, decls []*ast.GenDecl, project string, opt *options) string {
	if len(specs) == 0 { return "" }
	groups := groupImports(specs, project, opt)
	paragraphs := [][]importSpec{}
	for _, g := range orderedGroupNames(opt.importsOrder) {
		items := groups[g]
		if len(items) == 0 { continue }
		sortSpecs(items)
		if opt.separateNamed {
			var unnamed, named []importSpec
			for _, sp := range items {
				if sp.Name == "" { unnamed = append(unnamed, sp) } else { named = append(named, sp) }
			}
			if len(unnamed) > 0 { paragraphs = append(paragraphs, unnamed) }
			if len(named) > 0 { paragraphs = append(paragraphs, named) }
		} else {
			paragraphs = append(paragraphs, items)
		}
	}
	// Include any imports classified into groups omitted from the requested order, preserving safety.
	seenGroups := map[string]bool{}
	for _, g := range orderedGroupNames(opt.importsOrder) { seenGroups[g] = true }
	for _, g := range []string{"std", "general", "company", "project", "blanked", "dotted"} {
		if seenGroups[g] || len(groups[g]) == 0 { continue }
		items := groups[g]; sortSpecs(items); paragraphs = append(paragraphs, items)
	}
	if len(paragraphs) == 0 { return "" }
	singleOriginal := len(specs) == 1 && len(decls) == 1 && decls[0].Lparen == token.NoPos
	if singleOriginal && len(paragraphs) == 1 && len(paragraphs[0]) == 1 && len(paragraphs[0][0].Doc) == 0 {
		return "import " + specLine(paragraphs[0][0], false) + "\n"
	}
	var b strings.Builder
	b.WriteString("import (\n")
	for pi, para := range paragraphs {
		if pi > 0 { b.WriteByte('\n') }
		for _, sp := range para {
			for _, c := range sp.Doc { b.WriteString("\t"+c+"\n") }
			b.WriteString("\t")
			b.WriteString(specLine(sp, true))
			b.WriteByte('\n')
		}
	}
	b.WriteString(")\n")
	return b.String()
}

func specLine(sp importSpec, inBlock bool) string {
	var s string
	if sp.Name != "" { s = sp.Name + " " }
	s += strconv.Quote(sp.Path)
	if len(sp.Comment) > 0 { s += " " + strings.Join(sp.Comment, " ") }
	return s
}

func orderedGroupNames(order string) []string {
	var out []string
	for _, p := range strings.Split(order, ",") {
		p = strings.TrimSpace(p)
		if p != "" { out = append(out, p) }
	}
	if len(out) == 0 { return []string{"std", "general", "company", "project"} }
	return out
}

func groupImports(specs []importSpec, project string, opt *options) map[string][]importSpec {
	groups := map[string][]importSpec{"std":{}, "general":{}, "company":{}, "project":{}, "blanked":{}, "dotted":{}}
	orderHas := map[string]bool{}
	for _, g := range orderedGroupNames(opt.importsOrder) { orderHas[g] = true }
	companies := splitCSV(opt.companyPrefixes)
	for _, sp := range specs {
