		if sp.Name == "_" && orderHas["blanked"] { g = "blanked" } else if sp.Name == "." && orderHas["dotted"] { g = "dotted" } else if isProjectImport(sp.Path, project) { g = "project" } else if isStdImport(sp.Path) { g = "std" } else if len(companies) > 0 && hasAnyPrefix(sp.Path, companies) { g = "company" }
		groups[g] = append(groups[g], sp)
	}
	return groups
}

func splitCSV(s string) []string {
	var out []string
	for _, p := range strings.Split(s, ",") {
		p = strings.TrimSpace(p)
		if p != "" { out = append(out, p) }
	}
	return out
}

func hasAnyPrefix(path string, prefixes []string) bool {
	for _, p := range prefixes {
		if path == p || strings.HasPrefix(path, strings.TrimRight(p, "/")+"/") { return true }
	}
	return false
}

func isProjectImport(path, project string) bool {
	if project == "" { return false }
	project = strings.TrimRight(project, "/")
	return path == project || strings.HasPrefix(path, project+"/")
