p=Path('main.go')
s=p.read_text()
s=s.replace('\n\t"errors"', '')
s=s.replace('\nvar _ = errors.New\n', '\n')
old='''func versionAlias(path string) string {
	parts := strings.Split(path, "/")
	if len(parts) < 2 {
		return ""
	}
	last := parts[len(parts)-1]
	if !isVersionSegment(last) {
		return ""
	}
	return sanitizeIdent(parts[len(parts)-2])
}
'''
new='''func versionAlias(path string) string {
	parts := strings.Split(path, "/")
	if len(parts) == 0 {
		return ""
	}
	last := parts[len(parts)-1]
	if isVersionSegment(last) && len(parts) >= 2 {
		return sanitizeIdent(parts[len(parts)-2])
	}
	if dot := strings.LastIndex(last, ".v"); dot > 0 && isVersionSegment(last[dot+1:]) {
		return sanitizeIdent(last[:dot])
	}
	return ""
}
'''
if old not in s:
    raise SystemExit('old not found')
s=s.replace(old,new)
p.write_text(s)
PY
gofmt -w main.go
./compile.sh
./executable -version-only && grep -n '"errors"\|var _' -n main.go || true
